import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{"title":"Dépannage"},"headers":[],"relativePath":"guide/depannage.md","filePath":"guide/depannage.md"}'),r={name:"guide/depannage.md"};function d(i,e,c,s,l,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h1><h2 id="commencez-par-daimon-doctor" tabindex="-1">Commencez par <code>daimon_doctor</code> <a class="header-anchor" href="#commencez-par-daimon-doctor" aria-label="Permalink to &quot;Commencez par `daimon_doctor`&quot;">​</a></h2><p>Demandez à votre IA d&#39;appeler <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>. C&#39;est un diagnostic en lecture seule, sans paramètre, qui ne peut pas faire apparaître de boîte de dialogue. Il rend :</p><table tabindex="0"><thead><tr><th>Clé</th><th>Ce qu&#39;elle vous dit</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Verdict global</td></tr><tr><td><code>responsible_app</code></td><td>L&#39;application à laquelle macOS rattache les autorisations</td></tr><tr><td><code>permissions</code></td><td>Enregistrement de l&#39;écran et Accessibilité : accordées ou non</td></tr><tr><td><code>consequences</code></td><td>Ce que chaque autorisation manquante fait à chaque outil</td></tr><tr><td><code>exclusions</code></td><td>État du fichier d&#39;exclusions</td></tr><tr><td><code>ceiling</code></td><td>Plafond actif</td></tr><tr><td><code>cannot_detect</code></td><td>Ce que le diagnostic ne peut pas détecter</td></tr><tr><td><code>next</code></td><td>Prochaines étapes suggérées</td></tr></tbody></table><p>Lisez <code>cannot_detect</code> : l&#39;absence de problème rapportée n&#39;est pas une preuve pour ce qui y figure.</p><h2 id="symptomes" tabindex="-1">Symptômes <a class="header-anchor" href="#symptomes" aria-label="Permalink to &quot;Symptômes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptôme</th><th>Piste</th></tr></thead><tbody><tr><td>Les captures échouent (macOS)</td><td>Autorisation <strong>Enregistrement de l&#39;écran</strong> manquante pour l&#39;application responsable : voir <a href="./autorisations.html">Autorisations</a></td></tr><tr><td><code>main_type</code>, <code>main_key</code>, <code>main_hover</code> ou <code>main_navigate</code> rendent <code>done</code> sans effet</td><td>Autorisation <strong>Accessibilité</strong> manquante</td></tr><tr><td><code>main_click</code>, <code>main_press</code> ou <code>main_drag</code> attendent longtemps</td><td>Sans Accessibilité, ils attendent 30 secondes une boîte de confirmation</td></tr><tr><td>Une action est refusée</td><td>Le plafond est trop bas pour cet outil : appelez <a href="/Daimon/reference/diagnostic.html#main-ceiling"><code>main_ceiling</code></a>, et réglez le curseur du panneau si vous le souhaitez</td></tr><tr><td>Une capture est refusée</td><td>Une application de <code>exclusions.yaml</code> est au premier plan, ou le fichier est cassé : consultez la clé <code>exclusions</code> de <code>daimon_doctor</code></td></tr><tr><td>Les repères de l&#39;Overlay n&#39;apparaissent pas</td><td>Les outils répondent <code>ok</code> même sans fenêtre d&#39;overlay ; activez <strong>Présence à l&#39;écran</strong> dans le panneau, puis lisez la clé <code>overlay</code> de <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> (<code>listening</code>, <code>last_log_line</code>) ; les repères n&#39;apparaissent dans aucune capture d&#39;écran, c&#39;est voulu</td></tr><tr><td>Votre client ne voit pas Daimon</td><td>Redémarrez le client ; vérifiez avec <code>Daimon status</code> ; Daimon doit être installé avant l&#39;enregistrement ; <code>Daimon install</code> réécrit l&#39;entrée : voir <a href="./clients-mcp.html">Clients IA</a></td></tr><tr><td>SmartScreen avertit (Windows)</td><td>Avertissement malgré la signature Authenticode (éditeur ArboRithm) : <strong>Informations complémentaires</strong>, puis <strong>Exécuter quand même</strong></td></tr><tr><td>L&#39;icône est introuvable (Windows)</td><td>Cherchez dans la zone de notification, éventuellement dans le menu de débordement</td></tr></tbody></table><h2 id="autorisations-accordees-mais-rien-ne-change" tabindex="-1">Autorisations accordées, mais rien ne change <a class="header-anchor" href="#autorisations-accordees-mais-rien-ne-change" aria-label="Permalink to &quot;Autorisations accordées, mais rien ne change&quot;">​</a></h2><p>macOS les rattache à l&#39;application qui lance Daimon. Accordez-les à celle que <code>responsible_app</code> nomme.</p><h2 id="signaler-un-probleme" tabindex="-1">Signaler un problème <a class="header-anchor" href="#signaler-un-probleme" aria-label="Permalink to &quot;Signaler un problème&quot;">​</a></h2><p><a href="https://github.com/ArboRithm/Daimon/issues" target="_blank" rel="noreferrer">Ouvrez une issue</a> ou écrivez à <a href="mailto:app@arborithm.fr" target="_blank" rel="noreferrer">app@arborithm.fr</a>.</p>',11)])])}const h=t(r,[["render",d]]);export{p as __pageData,h as default};
